-- Create replicated table definitions for MergeTree-family tables.
-- Review and execute only when the previous stage succeeded.

CREATE TABLE `analytics`.`authentications` (`id` UUID, `channelId` UUID, `providerId` UUID, `identityType` Enum8('IDENTITY_TYPE_UNSPECIFIED' = 0, 'PHONE' = 1, 'EMAIL' = 2), `clientIp` Nullable(String), `sourceType` Nullable(String), `sourceId` Nullable(String), `sourceUuid` Nullable(UUID), `state` Enum8('STATE_UNSPECIFIED' = 0, 'CREATING' = 1, 'PENDING' = 2, 'OTP_SENT' = 3, 'OTP_VERIFYING' = 4, 'OTP_INVALID' = 5, 'AUTHENTICATED' = 6, 'CANCELED' = 7, 'FAILED' = 8), `failReasonCode` Enum8('ERROR_CODE_UNSPECIFIED' = 0, 'OTP_INVALID' = 1, 'OTP_EXPIRED' = 2, 'OTP_DELIVERY_FAILED' = 3, 'UNKNOWN' = 4), `fallbackUsed` Nullable(Bool), `createTime` DateTime64(9, 'Europe/Moscow'), `updateTime` Nullable(DateTime64(9, 'Europe/Moscow')), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`authentications_channels` (`id` UUID, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `name` String, `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`authentications_providers` (`id` UUID, `type` Enum8('TYPE_UNSPECIFIED' = 0, 'MOBILE_ID' = 1, 'OTP_PUSH' = 2, 'OTP_SMS' = 3, 'OTP_TELEGRAM' = 4, 'OTP_VK' = 5, 'OTP_EMAIL' = 6), `name` String, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`bonus_logs` (`sourceId` UUID, `startTime` DateTime64(9, 'Europe/Moscow'), `endTime` Nullable(DateTime64(9, 'Europe/Moscow')), `new` Nullable(Bool), `success` Nullable(Bool), `cancel` Nullable(Bool), `client` String, `use_master_code` Nullable(Bool), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY (sourceId, client, startTime) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`employees` (`id` UUID, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `firstName` Nullable(String), `middleName` Nullable(String), `lastName` Nullable(String), `pfr` Nullable(String), `phone` Nullable(String), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`employees_companies` (`id` UUID, `employeeId` UUID, `name` Nullable(String), `type` Enum8('TYPE_UNSPECIFIED' = 0, 'MAIN' = 1, 'INNER' = 2, 'EXTERNAL' = 3), `hiringYear` Nullable(UInt16), `hiringMonth` Nullable(UInt8), `hiringDay` Nullable(UInt8), `dismissalYear` Nullable(UInt16), `dismissalMonth` Nullable(UInt8), `dismissalDay` Nullable(UInt8), `number` Nullable(String), `position` Nullable(String), `shopId` Nullable(UUID), `brand` Nullable(String), `departmentId` Nullable(UUID), `departmentName` Nullable(String), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY (employeeId, id) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`offers` (`id` String, `product_id` UUID, `sku` String, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `name` Nullable(String), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY sku SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`prices` (`productId` UUID, `typeId` UUID, `currencyId` UUID, `oldPrice` Float64, `price` Float64, `productExternalId` Nullable(UInt64), `vatId` Nullable(UUID), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY (productId, typeId, currencyId) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`prices_costs` (`skuId` String, `sku` Nullable(String), `currency` Nullable(String), `vat` UInt8, `price` Float64, `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY skuId SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`prices_types` (`id` UUID, `name` String, `storeId` Nullable(UUID), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`products` (`id` UUID, `sku` String, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `name` Nullable(String), `article` String, `brand` Nullable(String), `category` Nullable(String), `collection` Nullable(String), `construction` Nullable(String), `gender` Nullable(String), `nomenclatureKind` Nullable(String), `season` Nullable(String), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY sku SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`stores` (`id` UUID, `state` Enum8('STATE_UNSPECIFIED' = 0, 'ACTIVE' = 1, 'INACTIVE' = 2, 'DELETED' = 3), `name` Nullable(String), `displayName` Nullable(String), `brand` Nullable(String), `coordinates` Point, `mall` Nullable(String), `metro` Nullable(String), `phone` Nullable(String), `email` Nullable(String), `timeZone` Nullable(String), `externalId` Nullable(Int32), `partner` Nullable(Bool), `fiasId` Nullable(UUID), `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY id SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`stores_traffic` (`storeId` UUID, `dateTime` DateTime('Europe/Moscow'), `in` Int32, `out` Int32, `timestamp` DateTime64(9, 'Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree(timestamp) ORDER BY (storeId, dateTime) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`temp_onec_purchases_main` (`ИдентификаторДокумента` UUID, `ВидОперации` Nullable(String), `КассаККМ` UUID, `ТипЦен` Nullable(UUID), `СуммаДокумента` Nullable(Float64), `ЧекПробитНаККМ` Nullable(Bool), `НомерЧекаККМ` String, `ДатаЧекаККМ` DateTime('Europe/Moscow'), `СтатусДокумента` String, `НомерФД` Nullable(Int32), `НомерФН` Nullable(String), `БезПечатиЧека` Nullable(Bool), `SailPlay_НомерТелефона` Nullable(String), `SailPlay_НомерКарты` Nullable(String), `ФПД` Nullable(String), `timestamp` DateTime('Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYYYYMM(`ДатаЧекаККМ`) ORDER BY (toYYYYMM(`ДатаЧекаККМ`), `КассаККМ`, `НомерЧекаККМ`, `СтатусДокумента`, `ИдентификаторДокумента`) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`temp_onec_purchases_payments` (`ИдентификаторДокумента` UUID, `НомерЧекаККМ` String, `ВидОплаты` String, `Сумма` Nullable(Float64), `timestamp` DateTime('Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYYYYMM(timestamp) ORDER BY (toYYYYMM(timestamp), `ВидОплаты`, `НомерЧекаККМ`, `ИдентификаторДокумента`) SETTINGS index_granularity = 8192;

CREATE TABLE `analytics`.`temp_onec_purchases_products` (`ИдентификаторДокумента` UUID, `ДатаЧекаККМ` DateTime('Europe/Moscow'), `Номенклатура` String, `НоменклатураГуид` Nullable(UUID), `Количество` Nullable(Int32), `ЕдиницаИзмерения` Nullable(String), `Склад` UUID, `Цена` Nullable(Float64), `Коэффициент` Nullable(Float32), `Сумма` Nullable(Float64), `ХарактеристикаНоменклатуры` Nullable(String), `СерияНоменклатуры` Nullable(String), `ПроцентАвтоматическихСкидок` Nullable(Float32), `Штрихкод` Nullable(String), `Акция` Nullable(UUID), `ПродавецФИО` Nullable(String), `ПродавецИНН` Nullable(String), `ПродавецПФР` String, `GTIN` Nullable(String), `СерийныйНомерКодаМаркировки` Nullable(String), `КодМаркировки` Nullable(String), `SailPlay_СуммаСкидки` Nullable(Float64), `SailPlay_СуммаСкидкиОплатыБонусом` Nullable(Float64), `SailPlay_СуммаНачисленныхБонусов` Nullable(Float64), `SailPlay_МаксимальнаяСуммаОплатыБонусами` Nullable(Float64), `ЗаказПокупателя` Nullable(String), `timestamp` DateTime('Europe/Moscow')) ENGINE = ReplicatedReplacingMergeTree() PARTITION BY toYYYYMM(`ДатаЧекаККМ`) ORDER BY (toYYYYMM(`ДатаЧекаККМ`), `Склад`, `ПродавецПФР`, `Номенклатура`, `ИдентификаторДокумента`) SETTINGS index_granularity = 8192;

